import dev.dov.onetint.PreviewScene;
import dev.dov.onetint.MaterialWifi;
import dev.dov.onetint.MaterialVolume;
import dev.dov.onetint.ThemeOptions;
import java.util.Locale;
/** Development-only SVG adapter for the same scene drawn by the Android view. */
public class RenderPreview implements PreviewScene.Draw {
    StringBuilder svg=new StringBuilder();
    String f(float x){return String.format(Locale.US,"%.2f",x);}
    String fill(int color){return String.format(Locale.US,"fill=\"#%06X\" fill-opacity=\"%.4f\"",color&0xffffff,(color>>>24)/255f);}
    String stroke(int color,float width){return String.format(Locale.US,"fill=\"none\" stroke=\"#%06X\" stroke-opacity=\"%.4f\" stroke-width=\"%.2f\" stroke-linecap=\"round\" stroke-linejoin=\"round\"",color&0xffffff,(color>>>24)/255f,width);}
    public void box(float l,float t,float r,float b,float radius,int color){svg.append("<rect x=\"").append(f(l)).append("\" y=\"").append(f(t)).append("\" width=\"").append(f(r-l)).append("\" height=\"").append(f(b-t)).append("\" rx=\"").append(f(radius)).append("\" ").append(fill(color)).append("/>");}
    public void circle(float x,float y,float radius,int color){svg.append("<circle cx=\"").append(f(x)).append("\" cy=\"").append(f(y)).append("\" r=\"").append(f(radius)).append("\" ").append(fill(color)).append("/>");}
    public void line(float x,float y,float x2,float y2,float width,int color){svg.append("<path d=\"M").append(f(x)).append(',').append(f(y)).append('L').append(f(x2)).append(',').append(f(y2)).append("\" ").append(stroke(color,width)).append("/>");}
    public void arc(float l,float t,float r,float b,float start,float sweep,float width,int color){if(Math.abs(sweep)>=359.9f){arc(l,t,r,b,start,180,width,color);arc(l,t,r,b,start+180,180,width,color);return;}double a=Math.toRadians(start),z=Math.toRadians(start+sweep);float rx=(r-l)/2,ry=(b-t)/2,cx=(l+r)/2,cy=(t+b)/2;svg.append("<path d=\"M").append(f(cx+rx*(float)Math.cos(a))).append(',').append(f(cy+ry*(float)Math.sin(a))).append(" A").append(f(rx)).append(',').append(f(ry)).append(" 0 ").append(Math.abs(sweep)>180?1:0).append(',').append(sweep>=0?1:0).append(' ').append(f(cx+rx*(float)Math.cos(z))).append(',').append(f(cy+ry*(float)Math.sin(z))).append("\" ").append(stroke(color,width)).append("/>");}
    public void polygon(float[] p,int color){svg.append("<polygon points=\"");for(int i=0;i<p.length;i+=2)svg.append(f(p[i])).append(',').append(f(p[i+1])).append(' ');svg.append("\" ").append(fill(color)).append("/>");}
    public void text(String value,float cx,float baseline,float size,int color){svg.append("<text x=\"").append(f(cx)).append("\" y=\"").append(f(baseline)).append("\" font-family=\"sans-serif\" font-size=\"").append(f(size)).append("\" text-anchor=\"middle\" ").append(fill(color)).append('>').append(value.replace("&","&amp;").replace("<","&lt;")).append("</text>");}
    public void wifi(float cx,float cy,int color){svg.append("<path d=\"").append(MaterialWifi.PATH).append("\" transform=\"translate(").append(f(cx-13)).append(',').append(f(cy-13)).append(") scale(1.0833333)\" ").append(fill(color)).append("/>");}
    public void volumeIcon(float cx,float cy,int color){svg.append("<path d=\"").append(MaterialVolume.PATH).append("\" transform=\"translate(").append(f(cx-13)).append(',').append(f(cy-13)).append(") scale(1.0833333)\" ").append(fill(color)).append("/>");}
    public void textLeft(String value,float x,float baseline,float size,int color){svg.append("<text x=\"").append(f(x)).append("\" y=\"").append(f(baseline)).append("\" font-family=\"sans-serif\" font-size=\"").append(f(size)).append("\" ").append(fill(color)).append('>').append(value.replace("&","&amp;").replace("<","&lt;")).append("</text>");}
    public static void main(String[] args){RenderPreview out=new RenderPreview();int mode=Integer.parseInt(args[0]),height=PreviewScene.height(mode),surface=args.length>3?(int)(0xff000000L|Long.parseLong(args[3],16)):0xff757575;ThemeOptions options=new ThemeOptions();options.inactive=surface;options.quickIconsWhite=Boolean.parseBoolean(args[2]);options.volumeIconsWhite=args.length>4?Boolean.parseBoolean(args[4]):true;if(args.length>7){options.notificationBackground=ThemeOptions.rgb(args[5]);options.notificationText=ThemeOptions.rgb(args[6]);options.notificationIcons=ThemeOptions.rgb(args[7]);}PreviewScene.draw(out,312,mode,(int)(0xff000000L|Long.parseLong(args[1],16)),options,args.length>8?Integer.parseInt(args[8]):8,args.length>9?Integer.parseInt(args[9]):15);System.out.println("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"624\" height=\""+(height*2)+"\" viewBox=\"0 0 312 "+height+"\">"+out.svg+"</svg>");}
}
